  renderRestriction(sequence);renderComposition(sequence,composition);renderCompositionStatistics(sequence);renderTransformations(sequence);renderGC(sequence);renderORFs(sequence,state.orfs);renderFrames(sequence,frames);renderCodonUsage(sequence);renderMotifs(sequence);renderSequence(sequence);$('#sequence-inspector').textContent='Select a nucleotide or codon.';const notes=contextNotes(analysisOptions());$('#coding-context').innerHTML=`<p>${escapeHTML(notes[0])}</p><details><summary>Biological context and limitations</summary>${notes.slice(1).map(text=>`<p>${escapeHTML(text)}</p>`).join('')}</details>`;$('#orf-rule-label').textContent=startCodons(state.code,$('#orf-start-rule').value).join('/')+' → stop';if($('#motif-input').value.trim())searchMotif();else renderFindings();if(longest)$('#inspect-longest-orf').onclick=()=>{$('.longest-candidate [data-orf]').click();$('.orf-panel').scrollIntoView({behavior:motion(),block:'start'});};
