  const item=({orf,index},featured=false)=>`<button class="orf-item" data-orf="${index}"><span class="strand ${orf.strand==='+'?'plus':'minus'}">${orf.frame}</span><strong>${orf.start}–${orf.end}</strong><span>${orf.length.toLocaleString()} nt${featured?' · longest':''}</span><code>${escapeHTML(orf.protein.slice(0,45))}${orf.protein.length>45?'…':''}</code></button>`;
