    host.querySelector('.orf-detail').innerHTML=`<p>Frame ${orf.frame} | Positions ${orf.start}–${orf.end} | ${orf.length.toLocaleString()} nt including stop. Reads ${orf.strand==='+'?'increasing':'decreasing'} input coordinates; ${orf.startCodon} to ${orf.stopCodon}.${orf.unresolvedCodons?` ${orf.unresolvedCodons} unresolved internal codons; an earlier stop is possible.`:''}</p><details><summary>Complete candidate translation (${orf.protein.length-1} residues + stop)</summary><code>${escapeHTML(orf.protein)}</code></details>`;
