function codonTable(usage){if(!usage.rows.length)return '<p class="empty">No unambiguous complete codons in this frame.</p>';return `<p class="note">${usage.total} unambiguous codons counted; ${usage.ambiguous} codons containing ambiguity symbols excluded. Codon frequencies characterize composition across the complete selected frame, including stops. Selecting a candidate changes the frame; counts remain scoped to the full input.</p><div class="codon-table-wrap"><table class="codon-table"><thead><tr><th>Codon</th><th>Amino acid</th><th>Count</th><th>Frequency</th></tr></thead><tbody>${usage.rows.map(row=>`<tr><td><code>${row.codon}</code></td><td>${AA_FULL[row.aminoAcid]} <span class="aa-abbr">(${AA_NAMES[row.aminoAcid]}, ${row.aminoAcid})</span></td><td>${row.count}</td><td><span class="codon-frequency"><i style="width:${100*row.frequency}%"></i></span>${(100*row.frequency).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div>`;}
