    host.querySelectorAll('[data-start]').forEach(button=>button.onclick=()=>showRegion(sequence,Number(button.dataset.start),Number(button.dataset.end),'Pattern hit'));
    host.querySelector('[data-page="previous"]')?.addEventListener('click',()=>{page--;draw();});host.querySelector('[data-page="next"]')?.addEventListener('click',()=>{page++;draw();});
