  $('#repeat-results').innerHTML=`<div class="pattern-block"><strong>Tandem repeat tracts</strong><p class="note">Repeated adjacent units, 1–6 nt with at least 3 copies. Maximal non-overlapping tracts are prioritized for inspection.</p><div id="repeat-primary">${groups.primary.length?groups.primary.slice(0,6).map(repeat).join(''):'<p class="empty">No tandem repeat meets these criteria.</p>'}</div>${repeats.length?`<details id="repeat-all"><summary>All ${repeats.length} repeat detections, including shorter and overlapping patterns</summary><div id="repeat-all-page"></div></details>`:''}</div><div class="pattern-block"><details id="palindrome-all"><summary>Reverse-complement palindromes (${palindromes.length})</summary><p class="note">Exact unambiguous 4–12 nt intervals equal to their reverse complement.</p><div id="palindrome-page"></div></details></div>`;
