function updateMutationDemo(){const cases={synonymous:{label:'Synonymous substitution',ref:'ATGGCTTAA',alt:'ATGGCCTAA',detail:'GCT and GCC both encode alanine, so this coding substitution is synonymous in this standard-code example.'},missense:{label:'Missense substitution',ref:'ATGGAGTAA',alt:'ATGGTGTAA',detail:'GAG encodes glutamate and GTG encodes valine. This changes one amino acid in the displayed peptide.'},nonsense:{label:'Stop-gain substitution',ref:'ATGTGGTAA',alt:'ATGTAGTAA',detail:'TGG encodes tryptophan, while TAG is a stop codon. In a real transcript, downstream context determines whether the RNA or protein is further processed.'},insertion:{label:'One-base insertion',ref:'ATGAAACCCGGGTAA',alt:'ATGAAAACCCGGGTAA',detail:'A single inserted nucleotide shifts triplet grouping downstream of the insertion site.'},deletion:{label:'In-frame three-base deletion',ref:'ATGAAACCCGGGTAA',alt:'ATGAAAGGGTAA',detail:'Three nucleotides are removed, so downstream codon grouping is preserved in this coding example. The altered peptide is shorter by one residue.'},frameshift:{label:'Frameshift from one-base deletion',ref:'ATGAAACCCGGGTAA',alt:'ATGAACCCGGGTAA',detail:'One nucleotide is removed. The downstream triplets are regrouped, changing the peptide and potentially shifting the stop position.'}};const item=cases[$('#mutation-demo-select').value],refProtein=sixFrames(item.ref)[0].protein,altProtein=sixFrames(item.alt)[0].protein;$('#mutation-demo-result').innerHTML=`<p><strong>${item.label}</strong></p><div class="mutation-example-rows"><span>Reference</span><code>${item.ref}</code><code>${refProtein}</code><span>Altered</span><code>${item.alt}</code><code>${altProtein}</code></div><p>${item.detail}</p>`;}
