function makeSummary(){return state.records.length?findingsText(analysisOptions()):'';}
function exampleSourceMarkup(example){
  return `<p>${escapeHTML(example.source)}</p>${example.url?`<p><a href="${escapeHTML(example.url)}" target="_blank" rel="noreferrer">${escapeHTML(example.accession||'Telomere reference')}</a></p>`:''}${example.explore?`<p><strong>What to explore:</strong> ${escapeHTML(example.explore)}</p>`:''}${example.referenceFeatures?.length?`<p><strong>Selected reference annotations (input coordinates):</strong> ${example.referenceFeatures.map(f=>`${escapeHTML(f.gene)} ${escapeHTML(f.location)} · ${f.residues} residues (${escapeHTML(f.proteinId)})`).join('; ')}.</p>`:''}`;
}
function clearExampleSelection(){
  document.querySelectorAll('[data-example]').forEach(card=>card.setAttribute('aria-pressed','false'));
  $('#example-introduction').textContent='Choose a sequence to explore its composition, patterns and coding intervals.';
  $('#selected-example-source').hidden=true;$('#example-status').hidden=true;
}
function initializeExamples(){
  $('#curated-examples').innerHTML=CURATED_KEYS.map(key=>{const example=EXAMPLES[key];return `<button class="example-choice" data-example="${key}" aria-pressed="false" title="${escapeHTML(example.introduction)}"><strong>${escapeHTML(example.title)}</strong><small>${example.sequence.length.toLocaleString()} nt${example.synthetic?' · synthetic':''}</small></button>`;}).join('');
  $('#example-select').innerHTML='<optgroup label="Earlier teaching examples">'+Object.keys(EXAMPLES).filter(key=>!CURATED_KEYS.includes(key)).map(key=>`<option value="${key}">${escapeHTML(EXAMPLES[key].name)}</option>`).join('')+'</optgroup>';
  $('#curated-source-list').innerHTML=CURATED_KEYS.map(key=>`<details><summary>${escapeHTML(EXAMPLES[key].title)} · ${EXAMPLES[key].sequence.length.toLocaleString()} nt</summary>${exampleSourceMarkup(EXAMPLES[key])}</details>`).join('');
  document.querySelectorAll('[data-example]').forEach(button=>button.onclick=()=>loadExample(button.dataset.example));
}
function loadExample(key,{run=false}={}){
  const example=EXAMPLES[key];if(!example)return;
  if([...$('#example-select').options].some(option=>option.value===key))$('#example-select').value=key;$('#sequence-name').value=example.name;$('#sequence-input').value=`>${example.name}\n${example.sequence}`;
  $('#genetic-code').value=example.code||(key==='mt-code'?'2':'1');$('#min-orf').value=example.minimum||(key==='mt-code'?3:key==='synthetic'?9:30);
  $('#gc-window').value=example.gcWindow||30;$('#codon-frame').value='+1';$('#frame-codon-start').value='1';
  $('#biological-source').value=example.biologicalSource||(key==='mt-code'?'organellar':key.startsWith('hbb')?'eukaryotic':'unspecified');
  $('#sequence-type').value=example.sequenceType||(key.startsWith('hbb')?'coding':'unknown');$('#orf-start-rule').value=example.startRule||'atg';$('#motif-input').value=example.motif||'ATG';$('#motif-mode').value='literal';$('#motif-reverse').checked=false;
  state.code=$('#genetic-code').value;state.records=[];state.features=null;$('#results').hidden=true;$('#error-message').hidden=true;
  document.querySelectorAll('[data-example]').forEach(card=>card.setAttribute('aria-pressed',String(card.dataset.example===key)));
  $('#example-introduction').textContent=example.introduction||example.source;$('#example-provenance').innerHTML=exampleSourceMarkup(example);$('#selected-example-source').hidden=false;
  $('#example-status').hidden=false;$('#example-status').textContent=`Loaded ${example.sequence.length.toLocaleString()} nt. Genetic code table ${state.code}${example.startRule==='table'?'; table-defined initiation':''}. Ready to analyze.`;
  if($('#view-analyze').hidden){navigateWorkspace('analyze');$('#analysis').scrollIntoView({behavior:'auto',block:'start'});}if(run)analyze();
}
document.querySelector('.intro-actions a[href="#analysis"]')?.addEventListener('click',event=>{event.preventDefault();$('#analysis').scrollIntoView({behavior:motion(),block:'start'});$('#sequence-input').focus({preventScroll:true});});
$('#analyze-btn').onclick=analyze;$('#load-example').onclick=()=>loadExample($('#example-select').value,{run:true});document.querySelectorAll('[data-load-sequence="telomere"]').forEach(button=>button.onclick=()=>loadExample('telomere'));$('#try-example').onclick=()=>{loadExample('synthetic',{run:true});};$('#fasta-file').onchange=async event=>{const file=event.target.files?.[0];if(file){clearExampleSelection();$('#sequence-input').value=await file.text();$('#sequence-name').value=file.name;analyze();}};
for(const id of ['gc-window','min-orf','genetic-code','biological-source','sequence-type','orf-start-rule'])$('#'+id).onchange=rerender;$('#codon-frame').onchange=()=>{if(state.records.length){renderCodonUsage(state.records[state.active].sequence);renderFindings();}};$('#motif-mode').onchange=()=>state.records.length&&searchMotif();$('#motif-reverse').onchange=()=>state.records.length&&searchMotif();$('#motif-input').onchange=()=>state.records.length&&searchMotif();$('#motif-btn').onclick=searchMotif;$('#compare-btn').onclick=align;$('#motif-input').addEventListener('keydown',event=>{if(event.key==='Enter')searchMotif();});
$('#copy-btn').onclick=()=>copyResult(makeSummary(),$('#copy-btn'),'Summary');$('#csv-btn').onclick=()=>{try{const record=state.records[state.active];download('seqscope-analysis.csv',analysisCSV(analysisOptions()),'text/csv;charset=utf-8');}catch(error){$('#export-status').hidden=false;$('#export-status').textContent=`CSV export: ${error.message}`;}};$('#fasta-btn').onclick=()=>download('analyzed-sequences.fasta',state.records.map(record=>`>${record.header}\n${record.sequence.match(/.{1,70}/g).join('\n')}`).join('\n'),'text/plain;charset=utf-8');$('#print-btn').onclick=async()=>{try{prepareReport();}catch(error){$('#export-status').hidden=false;$('#export-status').textContent=`Print report: ${error.message}`;return;}try{await $('#print-report .report-logo')?.decode?.();}catch{const status=$('#export-status');status.hidden=false;status.textContent='The report logo could not load. Please try printing again.';return;}window.print();};
initializeExamples();$('#restriction-method').textContent=RESTRICTION_METHOD;
$('#sequence-input').addEventListener('input',clearExampleSelection);
$('#load-hbb-comparison').onclick=()=>{$('#compare-a').value=HBB_COMPARISON.reference;$('#compare-b').value=HBB_COMPARISON.alternate;$('#compare-example-note').hidden=false;$('#compare-example-note').innerHTML='Matched 444-nt HBB CDSs from NM_000518.5: reference versus a reconstructed c.20A&gt;T teaching variant. Codon 7 changes GAG (Glu) to GTG (Val); mature beta-globin calls this residue 6. <a href="https://www.ncbi.nlm.nih.gov/clinvar/variation/15333/" target="_blank" rel="noreferrer">Variant source</a>.';align();};
initializePrintView();prepareReport=initializePrintReport(()=>!$('#results').hidden&&state.records.length?analysisOptions():null);initializeExplorers();$('#mutation-frame').innerHTML=$('#codon-frame').innerHTML;$('#mutation-code').innerHTML=$('#genetic-code').innerHTML;
$('#mutation-input').value='ATGGAGTAA';$('#mutate-btn').onclick=updateMutation;
$('#mutation-hbb').onclick=()=>{$('#mutation-input').value=EXAMPLES['hbb-cds'].sequence;$('#mutation-position').value='20';$('#mutation-base').value='T';$('#mutation-frame').value='+1';$('#mutation-code').value='1';updateMutation();};
$('#mutation-current').onclick=()=>{try{const records=parseInput($('#sequence-input').value);$('#mutation-input').value=records[state.active]?.sequence||records[0].sequence;$('#mutation-code').value=$('#genetic-code').value;$('#mutation-frame').value=$('#codon-frame').value;updateMutation();}catch(error){$('#mutation-result').textContent=error.message;}};updateMutation();$('#mutation-demo-select').onchange=updateMutationDemo;updateMutationDemo();initializeSchematics();navigateWorkspace=initializeNavigation({beforeDisplay:initializeNotesView()});

$('#clear-input').onclick=()=>{$('#sequence-input').value='';$('#example-introduction').textContent='Choose a sequence to explore its composition, patterns and coding intervals.';$('#selected-example-source').hidden=true;$('#example-status').hidden=true;$('#sequence-input').focus();$('#error-message').hidden=true;document.querySelectorAll('[data-example]').forEach(card=>card.setAttribute('aria-pressed','false'));};
$('#composition-chart').addEventListener('click',event=>{const button=event.target.closest('[data-base]');if(button)$('#composition-note').textContent=button.getAttribute('aria-label')+'. Percentages here use the full input length, including ambiguous symbols.';});
